public class InnerConnectionTypeSourceConfigurationFactory(Action<Humidifier.Glue.ConnectionTypeTypes.SourceConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Glue.ConnectionTypeTypes.SourceConfiguration>
{

    internal InnerConnectionTypeResponseConfigurationFactory ResponseConfigurationFactory { get; set; }

    internal InnerConnectionTypeFilterConfigurationFactory FilterConfigurationFactory { get; set; }

    internal InnerConnectionTypePaginationConfigurationFactory PaginationConfigurationFactory { get; set; }

    protected override Humidifier.Glue.ConnectionTypeTypes.SourceConfiguration Create()
    {
        var sourceConfigurationResult = CreateSourceConfiguration();
        factoryAction?.Invoke(sourceConfigurationResult);

        return sourceConfigurationResult;
    }

    private Humidifier.Glue.ConnectionTypeTypes.SourceConfiguration CreateSourceConfiguration()
    {
        var sourceConfigurationResult = new Humidifier.Glue.ConnectionTypeTypes.SourceConfiguration();

        return sourceConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Glue.ConnectionTypeTypes.SourceConfiguration result)
    {
        base.CreateChildren(result);

        result.ResponseConfiguration ??= ResponseConfigurationFactory?.Build();
        result.FilterConfiguration ??= FilterConfigurationFactory?.Build();
        result.PaginationConfiguration ??= PaginationConfigurationFactory?.Build();
    }

} // End Of Class

